# Solutions — Post-Doc, Tier 0 (Algorithmes Classiques et Closures)

### tache_0a — Curry auto-exécutant
```javascript
function curry(fn) {
  const arity = fn.length;
  return function curried(...args) {
    if (args.length >= arity) {
      return fn.apply(this, args);
    }
    return function (...more) {
      return curried.apply(this, args.concat(more));
    };
  };
}

// Tests :
// const add = curry((a, b, c) => a + b + c);
// add(1)(2)(3)   -> 6
// add(1, 2)(3)   -> 6
// add(1)(2, 3)   -> 6
// add(1, 2, 3)   -> 6
```

### tache_0b — Égalité profonde
```javascript
function egalProfond(a, b) {
  if (a === b) return true;
  // NaN === NaN est false : on considère deux NaN comme identiques
  if (a !== a && b !== b) return true;
  if (a === null || b === null || a === undefined || b === undefined) return false;
  if (typeof a !== 'object' || typeof b !== 'object') return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;

  // Dates
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }

  // Tableaux
  if (Array.isArray(a)) {
    if (a.length !== b.length) return false;
    for (let i = 0; i < a.length; i++) {
      if (!egalProfond(a[i], b[i])) return false;
    }
    return true;
  }

  // Objets simples
  const clesA = Object.keys(a);
  const clesB = Object.keys(b);
  if (clesA.length !== clesB.length) return false;
  for (const cle of clesA) {
    if (!Object.prototype.hasOwnProperty.call(b, cle)) return false;
    if (!egalProfond(a[cle], b[cle])) return false;
  }
  return true;
}

// Tests :
// egalProfond({a:{b:1}}, {a:{b:1}})  -> true
// egalProfond([1,[2,3]], [1,[2,3]]) -> true
// egalProfond({a:1}, {a:2})          -> false
// egalProfond(null, null)            -> true
```

### tache_0c — Composition de fonctions (droite → gauche)
```javascript
function composer(...fns) {
  return function (...args) {
    if (fns.length === 0) return args[0];
    // La fonction la plus à droite reçoit les arguments initiaux
    let resultat = fns[fns.length - 1](...args);
    // Puis on applique les suivantes de droite à gauche
    for (let i = fns.length - 2; i >= 0; i--) {
      resultat = fns[i](resultat);
    }
    return resultat;
  };
}

// Tests :
// composer(x => x + 1, x => x * 2)(3)      -> 7   (3*2=6, puis 6+1=7)
// composer(x => x * 3, x => x + 1, x => x * 2)(5) -> 33 (5*2=10, +1=11, *3=33)
// composer()(42)                            -> 42 (identité)
```

### tache_0d — Arbre binaire de recherche (insert + contains)
```javascript
function creerBST() {
  let racine = null;

  function creerNoeud(val) {
    return { val: val, gauche: null, droite: null };
  }

  function insert(val) {
    if (racine === null) {
      racine = creerNoeud(val);
      return;
    }
    let courant = racine;
    while (true) {
      if (val < courant.val) {
        if (courant.gauche === null) {
          courant.gauche = creerNoeud(val);
          return;
        }
        courant = courant.gauche;
      } else if (val > courant.val) {
        if (courant.droite === null) {
          courant.droite = creerNoeud(val);
          return;
        }
        courant = courant.droite;
      } else {
        return; // doublon : ignoré
      }
    }
  }

  function contains(val) {
    let courant = racine;
    while (courant !== null) {
      if (val === courant.val) return true;
      if (val < courant.val) courant = courant.gauche;
      else courant = courant.droite;
    }
    return false;
  }

  return { insert: insert, contains: contains };
}

// Tests :
// const bst = creerBST();
// [50, 30, 70, 20, 40, 60, 80].forEach(v => bst.insert(v));
// bst.contains(40) -> true
// bst.contains(45) -> false
```

### tache_0e — Memoization
```javascript
function memoize(fn) {
  const cache = new Map();
  return function (...args) {
    const cle = JSON.stringify(args);
    if (cache.has(cle)) {
      return cache.get(cle);
    }
    const resultat = fn.apply(this, args);
    cache.set(cle, resultat);
    return resultat;
  };
}

// Tests :
// const double = memoize(x => x * 2);
// double(5) -> 10 (calculé)
// double(5) -> 10 (depuis le cache)
// double(7) -> 14 (calculé)
```

