# Solutions — Post-Doc, Classe 1 (Tier 1)

## tache_1a
File de priorité basée sur un **min-heap binaire** : `dequeue()` retire l'élément dont le numéro de priorité est le plus bas.
```javascript
function creerFilePriorite() {
  // Min-heap : l'élément avec la priorité (numéro) la plus basse sort en premier.
  // Exemple : enqueue('B',1); enqueue('A',3); enqueue('C',2);
  //            dequeue() -> 'B' ; dequeue() -> 'C' ; dequeue() -> 'A'
  const tas = []; // chaque noeud : { val, priorite }

  function echanger(i, j) {
    const temp = tas[i];
    tas[i] = tas[j];
    tas[j] = temp;
  }

  function remonter(index) {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (tas[index].priorite < tas[parent].priorite) {
        echanger(index, parent);
        index = parent;
      } else {
        break;
      }
    }
  }

  function descendre(index) {
    const n = tas.length;
    let i = index;
    while (true) {
      const gauche = 2 * i + 1;
      const droite = 2 * i + 2;
      let plusPetit = i;
      if (gauche < n && tas[gauche].priorite < tas[plusPetit].priorite) {
        plusPetit = gauche;
      }
      if (droite < n && tas[droite].priorite < tas[plusPetit].priorite) {
        plusPetit = droite;
      }
      if (plusPetit === i) break;
      echanger(i, plusPetit);
      i = plusPetit;
    }
  }

  return {
    enqueue(val, priorite) {
      tas.push({ val: val, priorite: priorite });
      remonter(tas.length - 1);
    },
    dequeue() {
      if (tas.length === 0) return null;
      const min = tas[0];
      const dernier = tas.pop();
      if (tas.length > 0) {
        tas[0] = dernier;
        descendre(0);
      }
      return min.val;
    },
    taille() {
      return tas.length;
    }
  };
}
```

## tache_1b
EventEmitter avec support de **plusieurs écouteurs par événement**.
```javascript
function creerEventEmitter() {
  const ecouteurs = new Map(); // evenement -> [fonctions]

  const emitter = {
    on(evenement, fn) {
      if (typeof fn !== 'function') return emitter;
      if (!ecouteurs.has(evenement)) {
        ecouteurs.set(evenement, []);
      }
      ecouteurs.get(evenement).push(fn);
      return emitter;
    },
    off(evenement, fn) {
      const liste = ecouteurs.get(evenement);
      if (!liste) return emitter;
      if (typeof fn !== 'function') {
        ecouteurs.delete(evenement); // sans fn : retire tous les écouteurs de l'événement
        return emitter;
      }
      const index = liste.indexOf(fn);
      if (index !== -1) {
        liste.splice(index, 1);
      }
      if (liste.length === 0) {
        ecouteurs.delete(evenement);
      }
      return emitter;
    },
    emit(evenement, ...args) {
      const liste = ecouteurs.get(evenement);
      if (!liste || liste.length === 0) return;
      const copie = liste.slice(); // snapshot : sûr même si un écouteur modifie la liste
      for (let i = 0; i < copie.length; i++) {
        copie[i](...args);
      }
    }
  };

  return emitter;
}
```

## tache_1c
Zip à la Python : s'arrête au tableau le plus court.
```javascript
function zip(...tableaux) {
  if (tableaux.length === 0) return [];

  // Longueur du plus court tableau
  let longueurMin = Infinity;
  for (let i = 0; i < tableaux.length; i++) {
    const t = tableaux[i];
    if (t === null || t === undefined || typeof t.length !== 'number') return [];
    if (t.length < longueurMin) longueurMin = t.length;
  }

  const resultat = [];
  for (let i = 0; i < longueurMin; i++) {
    const tuple = [];
    for (let j = 0; j < tableaux.length; j++) {
      tuple.push(tableaux[j][i]);
    }
    resultat.push(tuple);
  }
  return resultat;
}
// zip([1,2,3], ['a','b','c']) -> [[1,'a'],[2,'b'],[3,'c']]
// zip([1,2,3], ['a','b'])    -> [[1,'a'],[2,'b']]
```

## tache_1d
**Débogage BFS** — le bug : `pop()` (LIFO → parcours en profondeur) au lieu de `shift()` (FIFO → parcours en largeur).
```javascript
function parcoursEnLargeur(graphe, depart) {
  const visites = [];
  const file = [depart];
  while (file.length > 0) {
    // CORRECTION : shift() (FIFO) pour un vrai parcours en largeur (BFS).
    // L'original utilisait pop() (LIFO), ce qui donnait un parcours en profondeur (DFS).
    const noeud = file.shift();
    if (!visites.includes(noeud)) {
      visites.push(noeud);
      for (const voisin of (graphe[noeud] || [])) {
        if (!visites.includes(voisin)) {
          file.push(voisin);
        }
      }
    }
  }
  return visites;
}
```

## tache_1e
Proxy « Observable » **manuel** (sans le built-in `Proxy`) : interception get/set via le gestionnaire.
```javascript
function creerProxy(cible, gestionnaire) {
  if (cible === null || typeof cible !== 'object') cible = {};
  if (gestionnaire === null || typeof gestionnaire !== 'object') gestionnaire = {};

  // Traps, avec comportement par défaut si absents (comme un vrai Proxy)
  const getTrap = typeof gestionnaire.get === 'function'
    ? gestionnaire.get
    : function (c, p) { return c[p]; };
  const setTrap = typeof gestionnaire.set === 'function'
    ? gestionnaire.set
    : function (c, p, v) { c[p] = v; return true; };

  const proxy = {};

  // Chaque propriété existante de la cible est interceptée via un accesseur
  for (const prop of Object.keys(cible)) {
    Object.defineProperty(proxy, prop, {
      enumerable: true,
      configurable: true,
      get() {
        return getTrap.call(gestionnaire, cible, prop);
      },
      set(valeur) {
        setTrap.call(gestionnaire, cible, prop, valeur);
      }
    });
  }

  // Accès explicite get(prop) / set(prop, valeur) — gère aussi les propriétés dynamiques
  Object.defineProperty(proxy, 'get', {
    enumerable: false,
    configurable: true,
    writable: true,
    value: function (prop) {
      return getTrap.call(gestionnaire, cible, prop);
    }
  });
  Object.defineProperty(proxy, 'set', {
    enumerable: false,
    configurable: true,
    writable: true,
    value: function (prop, valeur) {
      return setTrap.call(gestionnaire, cible, prop, valeur);
    }
  });

  return proxy;
}
// Exemple :
// const p = creerProxy({ compteur: 1 }, {
//   get(c, prop) { return c[prop] * 10; },
//   set(c, prop, v) { c[prop] = v; }
// });
// p.compteur      -> 10   (intercepté par get)
// p.compteur = 5  ->      (intercepté par set, cible.compteur = 5)
// p.get('compteur') -> 50
```

