## algo_difficile_1
```javascript
function supprimerDoublons(tab) {
  if (!Array.isArray(tab)) return [];
  const vus = new Set();
  const resultat = [];
  for (let i = 0; i < tab.length; i++) {
    const valeur = tab[i];
    if (!vus.has(valeur)) {
      vus.add(valeur);
      resultat.push(valeur);
    }
  }
  return resultat;
}
// supprimerDoublons([1, 2, 2, 3, 1, 4]) -> [1, 2, 3, 4] (ordre de première occurrence conservé)
```

