### tache_2b
Subject multicast type RxJS : `next`/`error`/`complete`, `subscribe` (objet ou fonction) retournant un `unsubscribe`, état terminal rejoué aux abonnés tardifs, `next` ignoré après terminaison.

```javascript
function creerSubject() {
  const abonnes = [];
  let estTermine = false;
  let typeTerminal = null;      // 'error' | 'complete'
  let valeurTerminale = undefined;

  function notifierTerminal(type, valeur) {
    estTermine = true;
    typeTerminal = type;
    valeurTerminale = valeur;
    const instantane = abonnes.slice();
    abonnes.length = 0;
    for (const abonne of instantane) {
      if (abonne.desabonne) continue;
      abonne.desabonne = true;
      const rappel = abonne.observateur[type];
      if (typeof rappel === 'function') {
        try { rappel(valeur); } catch (e) { /* isoler l'erreur d'un abonné */ }
      }
    }
  }

  return {
    next(valeur) {
      if (estTermine) return;
      const instantane = abonnes.slice();
      for (const abonne of instantane) {
        if (abonne.desabonne) continue;
        const rappel = abonne.observateur.next;
        if (typeof rappel === 'function') {
          try { rappel(valeur); } catch (e) { /* isoler l'erreur d'un abonné */ }
        }
      }
    },
    error(erreur) {
      if (estTermine) return;
      notifierTerminal('error', erreur);
    },
    complete() {
      if (estTermine) return;
      notifierTerminal('complete', undefined);
    },
    subscribe(observateurOuFonction) {
      const observateur = typeof observateurOuFonction === 'function'
        ? { next: observateurOuFonction }
        : (observateurOuFonction != null ? observateurOuFonction : {});

      // Subject déjà terminé : rejouer l'événement terminal (comportement RxJS)
      if (estTermine) {
        const rappel = observateur[typeTerminal];
        if (typeof rappel === 'function') {
          try { rappel(valeurTerminale); } catch (e) {}
        }
        return { unsubscribe() {} };
      }

      const abonne = { observateur: observateur, desabonne: false };
      abonnes.push(abonne);

      return {
        unsubscribe() {
          if (abonne.desabonne) return;
          abonne.desabonne = true;
          const index = abonnes.indexOf(abonne);
          if (index !== -1) abonnes.splice(index, 1);
        }
      };
    }
  };
}
```

### tache_2c
Mémoïsation avec déduplication en vol : une seule Promise partagée par clé tant qu'elle est pendante ; les succès restent en cache, les échecs ne l'empoisonnent pas (retry possible), mais les appels concurrents partagent bien le même rejet.

```javascript
function memoiserAsync(fn) {
  const memoire = new Map(); // clé -> Promise partagée

  return function (...args) {
    const cle = JSON.stringify(args);

    // Résultat déjà mémoïsé OU promesse encore en vol : la réutiliser
    if (memoire.has(cle)) {
      return memoire.get(cle);
    }

    // Appel réel (exécuté immédiatement, avant tout await)
    let promesseBrute;
    try {
      promesseBrute = Promise.resolve(fn(...args));
    } catch (erreur) {
      promesseBrute = Promise.reject(erreur);
    }

    // En cas d'échec : retirer la clé pour ne pas empoisonner le cache.
    // Les appels concurrents partagent malgré tout la même promesse rejetée.
    const promessePartagee = promesseBrute.catch(function (erreur) {
      memoire.delete(cle);
      throw erreur;
    });

    memoire.set(cle, promessePartagee);
    return promessePartagee;
  };
}
```

