function remplirMatrice(grille, x, y, nouvelleValeur) {
    if (!Array.isArray(grille)) return grille;
    if (y < 0 || y >= grille.length || !Array.isArray(grille[y])) return grille;
    if (x < 0 || x >= grille[y].length) return grille;

    const valeurOriginale = grille[y][x];
    if (valeurOriginale === nouvelleValeur) return grille;

    const pile = [[x, y]];
    while (pile.length > 0) {
        const [cx, cy] = pile.pop();
        if (cy < 0 || cy >= grille.length) continue;
        const ligne = grille[cy];
        if (cx < 0 || cx >= ligne.length) continue;
        if (ligne[cx] !== valeurOriginale) continue;
        ligne[cx] = nouvelleValeur;
        pile.push([cx + 1, cy]);
        pile.push([cx - 1, cy]);
        pile.push([cx, cy + 1]);
        pile.push([cx, cy - 1]);
    }
    return grille;
}
