function remplirMatrice(grille, x, y, nouvelleValeur) {
  // Validation de base : la grille et la ligne cible doivent exister
  if (!Array.isArray(grille) || !Array.isArray(grille[y])) {
    return grille;
  }

  const nbLignes = grille.length;

  // Coordonnées hors limites : rien à faire
  if (y < 0 || y >= nbLignes || x < 0 || x >= grille[y].length) {
    return grille;
  }

  const valeurCible = grille[y][x];

  // Si la cellule a déjà la nouvelle valeur : ne rien faire (évite aussi toute boucle infinie)
  if (valeurCible === nouvelleValeur) {
    return grille;
  }

  // Flood fill itératif 4-directionnel (pile, pas de limite de récursion)
  const pile = [[x, y]];

  while (pile.length > 0) {
    const [cx, cy] = pile.pop();

    // Rester dans la grille
    if (cy < 0 || cy >= nbLignes || !Array.isArray(grille[cy]) ||
        cx < 0 || cx >= grille[cy].length) {
      continue;
    }

    // Ne repeindre que les cellules de même valeur que la cellule d'origine
    if (grille[cy][cx] !== valeurCible) {
      continue;
    }

    grille[cy][cx] = nouvelleValeur; // modification sur place

    // 4 voisins : droite, gauche, bas, haut
    pile.push([cx + 1, cy]);
    pile.push([cx - 1, cy]);
    pile.push([cx, cy + 1]);
    pile.push([cx, cy - 1]);
  }

  return grille;
}
