class LRUCache {
  constructor(capacite) {
    this.capacite = typeof capacite === 'number' ? Math.floor(capacite) : 0;
    this.map = new Map(); // Map conserve l'ordre d'insertion → O(1) pour get/put
  }

  get(cle) {
    if (!this.map.has(cle)) return -1;
    const valeur = this.map.get(cle);
    // Rafraîchit la clé (la déplace en fin = most recently used)
    this.map.delete(cle);
    this.map.set(cle, valeur);
    return valeur;
  }

  put(cle, valeur) {
    if (this.capacite <= 0) return;
    if (this.map.has(cle)) {
      this.map.delete(cle); // mise à jour → devient la plus récente
    } else if (this.map.size >= this.capacite) {
      // Le premier élément du Map est le moins récemment utilisé (LRU)
      const lru = this.map.keys().next().value;
      if (lru !== undefined) this.map.delete(lru);
    }
    this.map.set(cle, valeur);
  }
}
