        if (courant.gauche === null) {
          courant.gauche = creerNoeud(val);
          return;
        }
        courant = courant.gauche;
      } else if (val > courant.val) {
        if (courant.droite === null) {
          courant.droite = creerNoeud(val);
          return;
        }
        courant = courant.droite;
      } else {
        return; // doublon : ignoré
      }
    }
  }

  function contains(val) {
    let courant = racine;
    while (courant !== null) {
      if (val === courant.val) return true;
      if (val < courant.val) courant = courant.gauche;
      else courant = courant.droite;
    }
    return false;
  }

  return { insert: insert, contains: contains };
}

