## tache_1a
File de priorité basée sur un **min-heap binaire** : `dequeue()` retire l'élément dont le numéro de priorité est le plus bas.
```javascript
function creerFilePriorite() {
  // Min-heap : l'élément avec la priorité (numéro) la plus basse sort en premier.
  // Exemple : enqueue('B',1); enqueue('A',3); enqueue('C',2);
  //            dequeue() -> 'B' ; dequeue() -> 'C' ; dequeue() -> 'A'
  const tas = []; // chaque noeud : { val, priorite }

  function echanger(i, j) {
    const temp = tas[i];
    tas[i] = tas[j];
    tas[j] = temp;
  }

  function remonter(index) {
    while (index > 0) {
      const parent = Math.floor((index - 1) / 2);
      if (tas[index].priorite < tas[parent].priorite) {
        echanger(index, parent);
        index = parent;
      } else {
        break;
      }
    }
  }

  function descendre(index) {
    const n = tas.length;
    let i = index;
    while (true) {
      const gauche = 2 * i + 1;
      const droite = 2 * i + 2;
      let plusPetit = i;
      if (gauche < n && tas[gauche].priorite < tas[plusPetit].priorite) {
        plusPetit = gauche;
      }
      if (droite < n && tas[droite].priorite < tas[plusPetit].priorite) {
        plusPetit = droite;
      }
      if (plusPetit === i) break;
      echanger(i, plusPetit);
      i = plusPetit;
    }
  }

  return {
    enqueue(val, priorite) {
      tas.push({ val: val, priorite: priorite });
      remonter(tas.length - 1);
    },
    dequeue() {
      if (tas.length === 0) return null;
      const min = tas[0];
      const dernier = tas.pop();
      if (tas.length > 0) {
        tas[0] = dernier;
        descendre(0);
      }
      return min.val;
    },
    taille() {
      return tas.length;
    }
  };
}
```

## tache_1b
EventEmitter avec support de **plusieurs écouteurs par événement**.
```javascript
function creerEventEmitter() {
  const ecouteurs = new Map(); // evenement -> [fonctions]

  const emitter = {
    on(evenement, fn) {
      if (typeof fn !== 'function') return emitter;
      if (!ecouteurs.has(evenement)) {
        ecouteurs.set(evenement, []);
      }
      ecouteurs.get(evenement).push(fn);
      return emitter;
    },
    off(evenement, fn) {
      const liste = ecouteurs.get(evenement);
      if (!liste) return emitter;
      if (typeof fn !== 'function') {
        ecouteurs.delete(evenement); // sans fn : retire tous les écouteurs de l'événement
        return emitter;
      }
      const index = liste.indexOf(fn);
      if (index !== -1) {
        liste.splice(index, 1);
      }
      if (liste.length === 0) {
        ecouteurs.delete(evenement);
      }
      return emitter;
    },
    emit(evenement, ...args) {
      const liste = ecouteurs.get(evenement);
      if (!liste || liste.length === 0) return;
      const copie = liste.slice(); // snapshot : sûr même si un écouteur modifie la liste
      for (let i = 0; i < copie.length; i++) {
        copie[i](...args);
      }
    }
  };

  return emitter;
}
```

