```javascript
function zip(...tableaux) {
  if (tableaux.length === 0) return [];

  // Longueur du plus court tableau
  let longueurMin = Infinity;
  for (let i = 0; i < tableaux.length; i++) {
    const t = tableaux[i];
    if (t === null || t === undefined || typeof t.length !== 'number') return [];
    if (t.length < longueurMin) longueurMin = t.length;
  }

  const resultat = [];
  for (let i = 0; i < longueurMin; i++) {
    const tuple = [];
    for (let j = 0; j < tableaux.length; j++) {
      tuple.push(tableaux[j][i]);
    }
    resultat.push(tuple);
  }
  return resultat;
}
// zip([1,2,3], ['a','b','c']) -> [[1,'a'],[2,'b'],[3,'c']]
