### tache_2e
Circuit Breaker à 3 états (FERMÉ → OUVERT → DEMI-OUVERT) : après `seuil` échecs consécutifs le circuit s'ouvre et rejette tout appel pendant `delaiResetMs` ; ensuite un unique essai en demi-ouvert referme le circuit s'il réussit, sinon le rouvre pour un nouveau délai.

```javascript
function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  const ETAT_FERME = 'FERME';
  const ETAT_OUVERT = 'OUVERT';
  const ETAT_DEMI_OUVERT = 'DEMI_OUVERT';

  let etat = ETAT_FERME;
  let echecsConsecutifs = 0;
  let ouvertDepuis = 0;
  let essaiEnCours = false;

  function creerErreurRejet(contexte) {
    const erreur = new Error('Circuit breaker ' + contexte + ' : appel rejeté');
    erreur.circuitOuvert = true;
    return erreur;
  }

  function ouvrir() {
    etat = ETAT_OUVERT;
    ouvertDepuis = Date.now();
    essaiEnCours = false;
  }

  return function appeler(...args) {
    // Circuit ouvert : rejeter tous les appels pendant le délai de reset
    if (etat === ETAT_OUVERT) {
      if (Date.now() - ouvertDepuis >= delaiResetMs) {
        etat = ETAT_DEMI_OUVERT; // délai écoulé : passer en demi-ouvert
        essaiEnCours = false;
      } else {
        return Promise.reject(creerErreurRejet('ouvert'));
      }
    }

    // Demi-ouvert : un seul essai autorisé à la fois
    let estEssai = false;
    if (etat === ETAT_DEMI_OUVERT) {
      if (essaiEnCours) {
        return Promise.reject(creerErreurRejet('demi-ouvert'));
      }
      estEssai = true;
      essaiEnCours = true;
    }

    let promesseBrute;
    try {
      promesseBrute = Promise.resolve(fn(...args));
    } catch (erreur) {
      promesseBrute = Promise.reject(erreur);
    }

    return promesseBrute.then(
      function (resultat) {
        // Succès : remettre le compteur d'échecs consécutifs à zéro
        echecsConsecutifs = 0;
        if (estEssai) {
          etat = ETAT_FERME; // l'essai a réussi : refermer le circuit
          essaiEnCours = false;
        }
        return resultat;
      },
      function (erreur) {
        if (estEssai) {
          ouvrir(); // l'essai a échoué : rouvrir pour un nouveau délai
        } else {
          echecsConsecutifs++;
          if (echecsConsecutifs >= seuil) {
            ouvrir();
          }
        }
        throw erreur;
      }
    );
  };
}
```

