```javascript
function memoiserAsync(fn) {
  if (typeof fn !== "function") {
    throw new TypeError("memoiserAsync : l'argument doit être une fonction");
  }

  // Cache : clé sérialisée -> promesse (en cours OU déjà résolue).
  // Tant que la promesse est en cours, tout appel concurrent avec les mêmes
  // arguments récupère LA MÊME promesse : fn n'est jamais appelée en double.
  const cache = new Map();

  function remplaceur(cle, val) {
    if (val === undefined) {
      return "__undefined__";
    }
    if (typeof val === "function" || typeof val === "symbol") {
      return "__" + typeof val + "__:" + String(val);
    }
    if (typeof val === "bigint") {
      return "__bigint__:" + val.toString();
    }
    if (val instanceof Date) {
      return "__date__:" + val.getTime();
    }
    if (val instanceof RegExp) {
      return "__regexp__:" + val.toString();
    }
    if (val !== null && typeof val === "object" && !Array.isArray(val)) {
      const copie = {};
      const noms = Object.keys(val).sort();
      for (let i = 0; i < noms.length; i++) {
        copie[noms[i]] = val[noms[i]];
      }
      return copie;
    }
    return val;
  }

  function serialiser(valeur) {
    if (valeur === null) {
      return "null";
    }
    const type = typeof valeur;
    if (type === "undefined") {
      return "undefined";
    }
    if (type === "number") {
      return "number:" + valeur;
    }
    if (type === "string") {
      return "string:" + valeur;
    }
    if (type === "boolean") {
      return "boolean:" + valeur;
    }
    if (type === "bigint") {
      return "bigint:" + valeur.toString();
    }
    if (type === "function" || type === "symbol") {
      return type + ":" + String(valeur);
    }
    try {
      return "object:" + JSON.stringify(valeur, remplaceur);
    } catch (e) {
      return "object:" + String(valeur);
    }
  }

  function creerCle(args) {
    const parties = [];
    for (let i = 0; i < args.length; i++) {
      parties.push(serialiser(args[i]));
    }
    // JSON.stringify échappe les séparateurs : la clé est injective
    // (memo("a", "b") et memo("a,b") ne peuvent pas entrer en collision).
    return JSON.stringify(parties);
  }

  const memoisee = function (...args) {
    const contexte = this;
    const cle = creerCle(args);

    // Hit (promesse en cours ou déjà résolue) : même promesse renvoyée,
    // fn n'est PAS rappelée.
    if (cache.has(cle)) {
      return cache.get(cle);
    }

    // Miss : UN SEUL appel réel à fn, encapsulé dans une promesse
    // (les lancers synchrones de fn deviennent des rejets).
    const promesse = Promise.resolve().then(function () {
      return fn.apply(contexte, args);
