    cache.set(cle, promesse);

    // Anti-poison : en cas d'échec, l'entrée est invalidée pour permettre
    // un nouvel essai au prochain appel (les erreurs ne sont pas mémoïsées).
    promesse.catch(function () {
      if (cache.get(cle) === promesse) {
        cache.delete(cle);
      }
    });

    return promesse;
  };

  return memoisee;
