async function chargerEnParallele(urls, chargement) {
  const listeUrls = Array.isArray(urls) ? urls : [];
  const succes = [];
  const echecs = [];

  // Tous les chargements sont lancés IMMÉDIATEMENT (parallélisme réel).
  // Chaque promesse est « blindée » : elle ne rejette JAMAIS, elle résout
  // toujours avec { reussi, url, valeur }. Un échec local ne peut donc pas
  // court-circuiter Promise.all (aucun fail-fast). Promise.resolve().then(...)
  // encapsule aussi un chargement synchrone qui lancerait une exception.
  const promesses = listeUrls.map(function (url) {
    return Promise.resolve()
      .then(function () {
        return chargement(url);
      })
      .then(
        function (resultat) {
          return { reussi: true, url: url, valeur: resultat };
        },
        function () {
          return { reussi: false, url: url, valeur: null };
        }
      );
  });

  // Promise.all restitue les résultats DANS L'ORDRE des URLs,
  // quel que soit l'ordre réel de complétion.
  const resultats = await Promise.all(promesses);

  for (let i = 0; i < resultats.length; i++) {
    if (resultats[i].reussi === true) {
      succes.push(resultats[i].valeur);
    } else {
      echecs.push(resultats[i].url);
    }
  }

  return { succes: succes, echecs: echecs };
}

